}));

const items = $input.all();

const menRows = items
  .filter(i => i.json.__gender === 'men')
  .map(i => Array.isArray(i.json.row) ? i.json.row : Object.values(i.json.row || {}))
  .filter(r => r.some(v => String(v ?? '').trim() !== ''));

const womenRows = items
  .filter(i => i.json.__gender === 'women')
  .map(i => Array.isArray(i.json.row) ? i.json.row : Object.values(i.json.row || {}))
  .filter(r => r.some(v => String(v ?? '').trim() !== ''));

if (!menRows.length || !womenRows.length) {
  throw new Error(`Template sync failed. Men rows: ${menRows.length}; Women rows: ${womenRows.length}. Check that both files contain a sheet named "Jeans-Fill this" and that the workbook is an XLSX file.`);
}

const store = $getWorkflowStaticData('global');

store.meeshoTemplates = {
  updatedAt: new Date().toISOString(),
  men: {
    columns: 54,
    rows: menRows,
  },
  women: {
    columns: 56,
    rows: womenRows,
  },
};

return [{
  json: {
    status: 'Template library synced',
    updatedAt: store.meeshoTemplates.updatedAt,
    menRows: menRows.length,
    womenRows: womenRows.length,
  }
}];

const form = $('Meesho Catalog Form').first().json;
const store = $getWorkflowStaticData('global');

const templates = store.meeshoTemplates;
if (!templates?.men?.rows?.length || !templates?.women?.rows?.length) {
  throw new Error(
    'Template library is empty. In the same form choose "Sync Templates", upload both your current Men and Women template XLSX files, submit once, then use "Build Catalog".'
  );
}

const gender = String(form.gender || '').trim().toLowerCase();
if (!['men', 'women'].includes(gender)) {
  throw new Error('Gender must be Men or Women.');
}

const rows = templates[gender].rows;
const expectedCols = gender === 'men' ? 54 : 56; // Men A:BB, Women A:BD

const sourceMatchLabel = String(form.source_match || 'ID/name starts with').trim();
const sourceMatch = ({
  'ID/name starts with': 'id_name_starts_with',
  'ID/name exact': 'id_name_exact',
  'Product ID / Style ID exact': 'style_id_exact',
  'Group ID exact': 'group_id_exact',
  'SKU ID exact': 'sku_id_exact',
}[sourceMatchLabel] || sourceMatchLabel || 'id_name_starts_with');
const sourceKey = String(form.source_key || '').trim();
if (!sourceKey) throw new Error('Source Key is required.');

const normalize = v => String(v ?? '').trim().toLowerCase();
const rowValue = (row, idx) => row[idx] ?? '';
const nrmKey = normalize(sourceKey);

function matches(row) {
  switch (sourceMatch) {
    case 'id_name_exact':
      return normalize(rowValue(row, 0)) === nrmKey;

    case 'id_name_starts_with':
      return normalize(rowValue(row, 0)).startsWith(nrmKey);

    case 'style_id_exact':
      return normalize(rowValue(row, gender === 'men' ? 45 : 47)) === nrmKey;

    case 'group_id_exact':
      return normalize(rowValue(row, gender === 'men' ? 48 : 50)) === nrmKey;

    case 'sku_id_exact':
      return normalize(rowValue(row, gender === 'men' ? 46 : 48)) === nrmKey;

    default:
      throw new Error('Unknown Source Match option.');
  }
}

// The uploaded Meesho file is used only for its first 4 instruction/header rows.
// We intentionally replace row 5 onward with cloned rows from your template library.
const freshItems = $items('Extract Fresh Meesho', 0, 0);
if (!freshItems.length) throw new Error('The fresh Meesho XLSX could not be read.');

const freshRows = freshItems.map(i => {
  const r = Array.isArray(i.json?.row) ? i.json.row : Object.values(i.json || {});
  return Array.from({length: expectedCols}, (_, c) => r[c] ?? '');
});

const headerRows = freshRows.slice(0, 4);
const matchesRows = rows.filter(r => Array.isArray(r) && matches(r));

if (!matchesRows.length) {
  throw new Error(
    `No template rows matched Source Key "${sourceKey}". Try "ID/name starts with" and enter the beginning of the value from column A, such as "black wideleg 26".`
  );
}

const get = name => String(form[name] ?? '').trim();

const newIdPattern = get('new_id_name_pattern');
const newProductName = get('new_product_name');
const newStyleId = get('new_style_id');
const skuPattern = get('sku_pattern');

const image1 = get('image1');
const image2 = get('image2');
const image3 = get('image3');
const image4 = get('image4');

if (!newIdPattern) throw new Error('New ID / Name Pattern is required.');
if (!newProductName) throw new Error('New Product Name is required.');
if (!newStyleId) throw new Error('New Product ID / Style ID is required.');
if (!skuPattern) throw new Error('SKU Pattern is required.');
for (const [label, value] of [['Image 1',image1],['Image 2',image2],['Image 3',image3],['Image 4',image4]]) {
  if (!value) throw new Error(`${label} URL is required.`);
}

const colorIdx = 22; // W in both templates
const sizeIdx = gender === 'men'
  ? 4  // Variation / size is E
  : 4;

const priceFields = [
  ['meesho_price', 5],          // F
  ['return_price', 6],          // G
  ['mrp', 7],                   // H
];

function optionalNumber(name) {
  const raw = form[name];
  if (raw === undefined || raw === null || String(raw).trim() === '') return null;
  const num = Number(raw);
  if (!Number.isFinite(num) || num < 0) {
    throw new Error(`${name} must be a valid non-negative number.`);
  }
  return num;
}

const prices = Object.fromEntries(priceFields.map(([name]) => [name, optionalNumber(name)]));

function replaceTokens(pattern, row) {
  const size = String(row[sizeIdx] ?? '').trim();
  const color = String(row[colorIdx] ?? '').trim();
  const sourceId = String(row[0] ?? '').trim();
  return String(pattern)
    .replaceAll('{{size}}', size)
    .replaceAll('{{variation}}', size)
    .replaceAll('{{color}}', color)
    .replaceAll('{{source_id}}', sourceId)
    .replaceAll('{{style_id}}', newStyleId);
}

function buildIdName(row) {
  const replaced = replaceTokens(newIdPattern, row);
  if (newIdPattern.includes('{{')) return replaced;
  return `${replaced} ${String(row[sizeIdx] ?? '').trim()}`.trim();
}

function buildSku(row) {
  const replaced = replaceTokens(skuPattern, row);
  if (skuPattern.includes('{{')) return replaced;
  return `${replaced}-${String(row[sizeIdx] ?? '').trim()}`.replace(/-+$/,'');
}

// Image columns
const imageStartIdx = gender === 'men' ? 41 : 43; // AP or AR
// Product ID / Style ID
const styleIdx = gender === 'men' ? 45 : 47;      // AT or AV
// SKU ID
const skuIdx = gender === 'men' ? 46 : 48;        // AU or AW
// Group ID
const groupIdx = gender === 'men' ? 48-1 : 50-1;  // AW or AY (0-based => 46/49? corrected below)
const actualGroupIdx = gender === 'men' ? 48-1 : 50-1;

// Correct 0-based indices for the known columns:
const styleCol = gender === 'men' ? 45 : 47;
const skuCol = gender === 'men' ? 46 : 48;
const groupCol = gender === 'men' ? 48 : 50;

// Build each cloned variation row.
const outputDataRows = matchesRows.map(source => {
  const r = Array.from({length: expectedCols}, (_, c) => source[c] ?? '');

  // A, D
  r[0] = buildIdName(source);
  r[3] = newProductName;

  // F:G:H
  if (prices.meesho_price !== null) r[5] = prices.meesho_price;
  if (prices.return_price !== null) r[6] = prices.return_price;
  if (prices.mrp !== null) r[7] = prices.mrp;

  // Image 1-4
  r[imageStartIdx] = image1;
  r[imageStartIdx + 1] = image2;
  r[imageStartIdx + 2] = image3;
  r[imageStartIdx + 3] = image4;

  // Product ID / Style ID + SKU ID
  r[styleCol] = newStyleId;
  r[skuCol] = buildSku(source);

  // Optional Group ID override
  const newGroupId = get('new_group_id');
  if (newGroupId) r[groupCol] = newGroupId;

  return r;
});

const allRows = [...headerRows, ...outputDataRows];

// Convert the matrix into JSON items with numeric keys.
// Convert to File is configured with Header Row = false, so these keys are NOT written as headers;
// the values become Excel cells in column order.
return allRows.map(cells => {
  const json = {};
  for (let c = 0; c < expectedCols; c++) {
    json[String(c)] = cells[c] ?? '';
  }
  return { json };
});

