const data = $input.first().json;

// 1. GET AI RESPONSE
const raw =
  data.output?.[0]?.content?.[0]?.text ||
  data.output?.[0]?.content?.find(c => c.text)?.text ||
  '';

const text = String(raw).replace(/\\n/g, '\n').trim();

// 2. EXTRACT SUMMARY
const summaryMatch = text.match(/Summary\s*:\s*(.*?)(?=\n\s*Status\s*:|$)/is);
const summary = summaryMatch ? summaryMatch[1].trim() : 'No summary available.';

// 3. EXTRACT STATUS
const statusMatch = text.match(/Status\s*:\s*(Positive|Negative|Neutral)/i);
let status = statusMatch ? statusMatch[1].trim() : 'Neutral';
status = status.charAt(0).toUpperCase() + status.slice(1).toLowerCase();

// 4. GET SENDER EMAIL + NAME
const gmailFrom = $('Gmail — Get Full Reply').first().json.from;
const fromEmail = (gmailFrom?.value?.[0]?.address || '').trim().toLowerCase();
const fromName = gmailFrom?.value?.[0]?.name || '';

// 5. FIND THE LEAD ROW BY SENDER EMAIL (true branch of the IF node)
const rows = $('Check If Email Id = Lead Mail').all().map(i => i.json);

const rowEmails = r => Object.entries(r)
  .filter(([k, v]) => /mail/i.test(k) && typeof v === 'string')
  .map(([k, v]) => v.trim().toLowerCase());

const lead = rows.find(r => rowEmails(r).includes(fromEmail)) || null;

const pick = (r, re) => {
  if (!r) return '';
  const key = Object.keys(r).find(k => re.test(k));
  return key ? String(r[key] || '').trim() : '';
};

const companyName = pick(lead, /company|business/i);

return [{
  json: {
    Summary: summary,
    Status: status,
    FromEmail: fromEmail,
    FromName: fromName,
    first_name: fromName.split(' ')[0] || '',
    company_name: companyName || 'your business',
    LeadFound: !!lead
  }
}];

